/*
 * node_modules/mochinode/index.js — core loader for the SEVM stack.
 *
 * The MochiBerry engine resolves import specifiers relative to the importing
 * file and has no package resolution of its own. This module supplies the
 * missing half so that application code can look like ordinary Node code:
 *
 *   const { require } = await import('../../node_modules/mochinode/index.js');
 *   const express = await require('express');
 *
 * Two distinct worlds, deliberately kept apart:
 *
 *   mochi_modules/  native engine plugins — .dll/.so/.lbrct loaded straight
 *                   into the engine through the native module loader.
 *   node_modules/   JS/framework packages — scripts, but a package may also
 *                   ship native libraries (DLL/EXE/ELF) inside bin/.
 */

import * as std from 'mbjs:std';
import * as os from 'mbjs:os';
import { exec, run, execOrThrow, bytesToString } from './lib/process.js';

/**
 * Install the missing web/Node globals (timers, URL, TextEncoder, AbortController,
 * structuredClone, fetch, crypto).
 *
 * NOTE: mochiglobals must NOT be statically imported here — it imports mochicrypto
 * and mochiws, which both import loadNative() from this module. A static edge here
 * forms a cycle (mochinode -> mochiglobals -> mochiws -> mochinode) and the engine
 * defers the nested dynamic import inside it until after the entry module finishes,
 * so globals would land too late. A dynamic import from inside an async function
 * body resolves immediately, so it is safe.
 */
let globalsPromise = null;
export async function ensureGlobals() {
    if (!globalsPromise) globalsPromise = import('../mochiglobals/index.js');
    return globalsPromise;
}

export const version = '0.1.0';

const BUILTIN_ALIASES = {
    'fs': 'mochifs',
    'node:fs': 'mochifs',
    'fs/promises': 'mochifs',
    'node:fs/promises': 'mochifs',
    'path': 'mochipath',
    'node:path': 'mochipath',
    'child_process': 'mochinode',
    'node:child_process': 'mochinode',
    'util': 'mochiutil',
    'node:util': 'mochiutil',
    'crypto': 'mochicrypto',
    'node:crypto': 'mochicrypto',
    'events': 'mochievents',
    'node:events': 'mochievents',
    'buffer': 'mochibuffer',
    'node:buffer': 'mochibuffer',
    'stream': 'mochistream',
    'node:stream': 'mochistream',
    'stream/promises': 'mochistream',
    'node:stream/promises': 'mochistream',
    'os': 'mochios',
    'node:os': 'mochios',
    'url': 'mochiurl',
    'node:url': 'mochiurl',
    'zlib': 'mochizlib',
    'node:zlib': 'mochizlib',
    'net': 'mochinet',
    'node:net': 'mochinet',
    'tls': 'mochitls',
    'node:tls': 'mochitls',
    'http': 'mochihttp',
    'node:http': 'mochihttp',
    'https': 'mochihttps',
    'node:https': 'mochihttps',
    'async_hooks': 'mochiasync_hooks',
    'node:async_hooks': 'mochiasync_hooks',
    'timers': 'mochitimers',
    'node:timers': 'mochitimers',
    'diagnostics_channel': 'mochidiagnostics_channel',
    'node:diagnostics_channel': 'mochidiagnostics_channel',
    'perf_hooks': 'mochiperf_hooks',
    'node:perf_hooks': 'mochiperf_hooks',
    'worker_threads': 'mochiworker_threads',
    'node:worker_threads': 'mochiworker_threads',
    'process': 'mochiprocess',
    'node:process': 'mochiprocess',
    'module': 'mochimodule',
    'node:module': 'mochimodule',
    'fetch': 'mochifetch',
    'globals': 'mochiglobals',
};

/* ------------------------------------------------------------------ */
/* path helpers (node:path subset, no engine dependency)               */
/* ------------------------------------------------------------------ */

function str(v) {
    if (Array.isArray(v)) return String(v[0]);
    return String(v);
}

export function cwd() {
    return str(os.getcwd());
}

export function dirname(p) {
    const s = str(p).replace(/\\/g, '/');
    const i = s.lastIndexOf('/');
    return i <= 0 ? '/' : s.slice(0, i);
}

export function basename(p) {
    const s = str(p).replace(/\\/g, '/');
    const i = s.lastIndexOf('/');
    return i < 0 ? s : s.slice(i + 1);
}

export function join(...parts) {
    const out = [];
    for (const p of parts) {
        const s = str(p).replace(/\\/g, '/');
        if (!s) continue;
        if (out.length === 0) out.push(s.replace(/\/+$/, ''));
        else out.push(s.replace(/^\/+/, '').replace(/\/+$/, ''));
    }
    const joined = out.join('/');
    return joined.replace(/\/+/g, '/');
}

export function resolvePath(from, target) {
    if (/^([A-Za-z]:)?\//.test(str(target))) return str(target).replace(/\\/g, '/');
    return join(dirname(from), str(target));
}

export function isAbsolute(p) {
    return /^([A-Za-z]:)?\//.test(str(p));
}

/* ------------------------------------------------------------------ */
/* file helpers                                                         */
/* ------------------------------------------------------------------ */

export function readText(path) {
    const data = std.loadFile(str(path));
    if (data === undefined || data === null)
        throw new Error('mochinode: cannot read "' + path + '"');
    return String(data);
}

export function fileExists(path) {
    try {
        const st = os.stat(String(path));
        // os.stat() answers [stats, status]; a missing path gives [null, 2].
        if (Array.isArray(st))
            return st[0] !== null && st[0] !== undefined && Number(st[1] || 0) === 0;
        return !!st;
    } catch (e) {
        return false;
    }
}

/* ------------------------------------------------------------------ */
/* node_modules resolution                                              */
/* ------------------------------------------------------------------ */

function packageMain(dir) {
    const pj = join(dir, 'package.json');
    if (!fileExists(pj)) return null;
    try {
        const meta = JSON.parse(readText(pj));
        return meta.main || 'index.js';
    } catch (e) {
        return null;
    }
}

/*
 * Walk up from `fromDir` looking for node_modules/<name>.
 * Returns an absolute path to the entry file, or null.
 */
export function resolvePackage(name, fromDir) {
    let dir = str(fromDir).replace(/\\/g, '/');
    for (;;) {
        const candidate = join(dir, 'node_modules', name);
        if (fileExists(candidate)) {
            const main = packageMain(candidate);
            if (main) {
                const entry = join(candidate, main);
                if (fileExists(entry)) return entry;
            }
            const idx = join(candidate, 'index.js');
            if (fileExists(idx)) return idx;
        }
        const parent = dirname(dir);
        if (parent === dir || parent === '/' || parent === '') break;
        dir = parent;
    }
    return null;
}

/*
 * require(spec) — Node-flavoured, asynchronous.
 *
 *   'express'        -> node_modules/express (walking up from the caller)
 *   './local.js'     -> relative to the caller
 *   'mbjs:std'       -> engine built-in
 *   'mochinode_net.dll' -> native module, searched in mochi_modules/ and
 *                           in node_modules/<pkg>/bin/
 */
export async function require(spec, fromDir) {
    await ensureGlobals();
    const from = fromDir || cwd();
    const raw = String(spec);
    const s = BUILTIN_ALIASES[raw] || raw;

    if (s.startsWith('mbjs:'))
        return await import(s);

    const embeddedName = globalThis.__MOCHI_MODULE_NAME__;
    if (typeof embeddedName === 'function') {
        const name = embeddedName(s);
        if (name !== undefined && name !== null)
            return await import(String(name));
    }

    if (/\.(dll|so|dylib|lbrct|exe)$/i.test(s))
        return await loadNative(s, from);

    let target = null;
    if (s.startsWith('./') || s.startsWith('../') || s.startsWith('/') ||
        /^[A-Za-z]:[\\/]/.test(s)) {
        const abs = resolvePath(from, s);
        if (fileExists(abs) && !fileExists(join(abs, 'package.json')))
            target = abs;
        else if (fileExists(join(abs, 'package.json'))) {
            const main = packageMain(abs) || 'index.js';
            target = join(abs, main);
        } else {
            const idx = join(abs, 'index.js');
            if (fileExists(idx)) target = idx;
        }
    } else {
        target = resolvePackage(s, from);
    }

    if (!target)
        throw new Error("mochinode: cannot resolve module '" + s + "'");

    const mod = await import(target);
    return (mod && mod.default !== undefined && mod.__esModule !== true &&
            (mod.default === null || typeof mod.default === 'object'))
        ? Object.assign({}, mod.default, mod)
        : mod;
}

/*
 * loadNative(name, fromDir) — locate and import a native engine plugin.
 *
 * Search order:
 *   1. node_modules/<pkg>/bin/<name>   (package-bundled native library)
 *   2. mochi_modules/<name>            (engine plugin registry)
 *
 * `name` may be given with or without the extension.
 */
/* native arch suffix used in lib/<name>_<arch>.<ext> (e.g. mochizlib_x86_64.dll) */
function nativeArch() {
    const a = (typeof process !== 'undefined' && process && process.arch) || 'x64';
    return { x64: 'x86_64', arm64: 'aarch64', ia32: 'x86', arm: 'arm' }[a] || a;
}

export async function loadNative(name, fromDir) {
    const from = str(fromDir || cwd()).replace(/\\/g, '/');
    const raw = String(name);
    const ext = /\.(dll|so|dylib|lbrct|exe)$/i.exec(raw);
    const base = ext ? raw.slice(0, ext.index) : raw;
    const exts = ext ? [ext[0]] : ['.dll', '.so', '.dylib', '.lbrct'];

    const roots = [];
    let dir = from;
    for (;;) {
        roots.push(join(dir, 'node_modules'));
        roots.push(join(dir, 'mochi_modules'));
        const parent = dirname(dir);
        if (parent === dir || parent === '/' || parent === '') break;
        dir = parent;
    }

    for (const root of roots) {
        for (const e of exts) {
            // package-bundled: node_modules/<pkg>/bin/<name><ext>
            const pkgBin = join(root, base, 'bin', base + e);
            if (fileExists(pkgBin)) return await import(pkgBin);
            // per-module native layout: <root>/<name>/lib/<name>_<arch><ext> then <name><ext>
            const libDir = join(root, base, 'lib');
            const libArch = join(libDir, base + '_' + nativeArch() + e);
            if (fileExists(libArch)) return await import(libArch);
            const libPlain = join(libDir, base + e);
            if (fileExists(libPlain)) return await import(libPlain);
            // engine plugin: mochi_modules/<name><ext>
            const plugin = join(root, base + e);
            if (fileExists(plugin)) return await import(plugin);
            // engine plugin named exactly as given
            const asGiven = join(root, raw + (ext ? '' : ''));
            if (ext && fileExists(asGiven)) return await import(asGiven);
        }
    }

    throw new Error("mochinode: native module '" + raw + "' not found");
}

/*
 * resolveNativePath(name, fromDir) — locate a native plugin *without*
 * importing it. Same search order as loadNative(), but returns the absolute
 * path so callers can hand it to another API (e.g. dynalib()).
 */
export function resolveNativePath(name, fromDir) {
    const from = str(fromDir || cwd()).replace(/\\/g, '/');
    const raw = String(name);
    const ext = /\.(dll|so|dylib|lbrct|exe)$/i.exec(raw);
    const base = ext ? raw.slice(0, ext.index) : raw;
    const exts = ext ? [ext[0]] : ['.dll', '.so', '.dylib', '.lbrct'];

    const roots = [];
    let dir = from;
    for (;;) {
        roots.push(join(dir, 'node_modules'));
        roots.push(join(dir, 'mochi_modules'));
        const parent = dirname(dir);
        if (parent === dir || parent === '/' || parent === '') break;
        dir = parent;
    }

    for (const root of roots) {
        for (const e of exts) {
            const pkgBin = join(root, base, 'bin', base + e);
            if (fileExists(pkgBin)) return pkgBin;
            // per-module native layout: <root>/<name>/lib/<name>_<arch><ext> then <name><ext>
            const libDir = join(root, base, 'lib');
            const libArch = join(libDir, base + '_' + nativeArch() + e);
            if (fileExists(libArch)) return libArch;
            const libPlain = join(libDir, base + e);
            if (fileExists(libPlain)) return libPlain;
            const plugin = join(root, base + e);
            if (fileExists(plugin)) return plugin;
        }
    }
    return null;
}

export { exec, run, execOrThrow, bytesToString };

export default { version, require, loadNative, resolveNativePath, resolvePackage, join, dirname, basename, cwd, exec, run };
